# Generate the Ponder schematic from the same coordinates used in the server validator.
import gzip, struct, math
def st(x):
    b=x.encode('utf-8')
    return struct.pack('>H',len(b))+b
def named(t,n,p): return bytes([t])+st(n)+p
def i(v): return struct.pack('>i',v)
def lst(t,parts): return bytes([t])+i(len(parts))+b''.join(parts)
def cp(parts): return b''.join(parts)+bytes([0])
palette=[]; blocks=[]
def block(x,y,z,name,props=None):
    key=(name,tuple(sorted((props or {}).items())))
    if key not in palette: palette.append(key)
    blocks.append(cp([named(9,'pos',lst(3,[i(x),i(y),i(z)])),named(3,'state',i(palette.index(key)))]))
def write_scene(name):
    pal=[cp([named(8,'Name',st(name))]+([named(10,'Properties',cp([named(8,k,st(v)) for k,v in props]))] if props else [])) for name,props in palette]
    root_tag=named(10,'',cp([named(3,'DataVersion',i(3955)),named(9,'size',lst(3,[i(13),i(12),i(13)])),named(9,'palette',lst(10,pal)),named(9,'blocks',lst(10,blocks)),named(9,'entities',lst(0,[]))]))
    p=root/'src/main/resources/assets/beyond_unknown/ponder'/ (name+'.nbt')
    p.parent.mkdir(parents=True,exist_ok=True)
    p.write_bytes(gzip.compress(root_tag,mtime=0))
for x in range(13):
    for z in range(13): block(x,0,z,'minecraft:polished_deepslate')
for x in range(-5,6):
    for y in range(-5,6):
        if 4.3<=math.hypot(x,y)<=5.6:
            name='minecraft:lodestone' if (x,y)==(0,-5) else 'minecraft:crying_obsidian' if (x,y) in [(0,5),(-5,0),(5,0)] else 'minecraft:polished_deepslate'
            block(x+6,y+6,9,name)
for z in range(1,6): block(6,6,z,'create:shaft',{'axis':'z'})
block(6,6,6,'beyond_unknown:rift_drive',{'facing':'south'})
for x in range(-4,5):
    for y in range(-4,5):
        if 3<=math.hypot(x,y)<=4.3 or (x==0 or y==0):
            block(x+6,y+6,7,'minecraft:cut_copper')
write_scene('rift')
palette.clear();blocks.clear()
for x in range(13):
    for z in range(13): block(x,0,z,'minecraft:polished_deepslate')
for z in range(1,5): block(6,3,z,'create:shaft',{'axis':'z'})
block(6,3,5,'create_new_age:generator_coil',{'axis':'z'})
for u in range(-2,3):
    for v in range(-2,3):
        if (abs(u)==2 and abs(v)<=1) or (abs(v)==2 and abs(u)<=1):
            block(6+u,3+v,5,'create_new_age:netherite_magnet')
block(6,3,6,'create_new_age:carbon_brushes',{'facing':'north'})
for z in range(7,11): block(6,3,z,'create_new_age:overcharged_iron_wire_block')
block(6,3,11,'beyond_unknown:rift_drive',{'facing':'south'})
write_scene('rift_power')

# Deterministic original pixel textures, generated using only Python standard library.
import zlib, random
def png(path,pixels):
    def chunk(k,d):return struct.pack('>I',len(d))+k+d+struct.pack('>I',zlib.crc32(k+d)&0xffffffff)
    raw=b''.join(b'\x00'+bytes(c for pix in row for c in pix) for row in pixels)
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_bytes(b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',16,16,8,2,0,0,0))+chunk(b'IDAT',zlib.compress(raw))+chunk(b'IEND',b''))
colors={'lumen_log':(33,63,72),'lumen_log_top':(59,113,117),'lumen_leaves':(40,162,170),'amber_log':(78,48,60),'amber_log_top':(130,78,56),'amber_leaves':(208,114,45),'resonant_ore':(65,49,91),'resonant_crystal':(132,71,196),'lumen_lamp':(79,198,220),'ancient_brick':(44,42,61),'lumen_moss':(36,101,102)}
for name,base in colors.items():
    rng=random.Random(name); rows=[]
    for y in range(16):
        row=[]
        for x in range(16):
            n=rng.randrange(-18,19)
            if name.endswith('_log'): n+=22 if (x+((y//5)%2))%5==0 else -8
            if name.endswith('_top'): n+=20 if int(math.hypot(x-7.5,y-7.5))%3==0 else -12
            if name.endswith('_leaves'): n+=45 if rng.random()<.12 else -4
            if name=='resonant_ore' and rng.random()<.24: row.append((172,97,242));continue
            if name=='resonant_crystal': n+=35 if (x+y*2)%7<2 else -9
            if name=='ancient_brick': n-=22 if y%5==0 or (x+(y//5)*5)%8==0 else 0
            if name=='lumen_lamp' and (x in (0,1,14,15) or y in (0,1,14,15)):row.append((42,53,72));continue
            row.append(tuple(max(0,min(255,c+n)) for c in base))
        rows.append(row)
    png(root/'src/main/resources/assets/beyond_unknown/textures/block'/ (name+'.png'),rows)

# Original 0.5 terrain textures and transparent cross plants
for name,base in [["veilstone",[46,39,70]],["lumen_soil",[25,76,92]],["amber_soil",[100,62,55]],["violet_soil",[76,41,108]],["star_blossom",[70,221,238]],["amber_bloom",[252,172,67]],["hanging_light",[114,200,229]]]:
    rng=random.Random(name); rows=[]; plant=name in ('star_blossom','amber_bloom','hanging_light')
    for y in range(16):
        row=[]
        for x in range(16):
            n=rng.randrange(-16,17)+int(10*math.sin(x*.9+y*.35))
            if not plant:
                if (x+y*2)%11==0:n+=26
                row.append(tuple(max(0,min(255,c+n)) for c in base))
            else:
                stem=abs(x-7.5)<1.5 and y>4
                petal=abs(x-7.5)+abs(y-4)<5 or (name=='hanging_light' and abs(x-7.5)<2.5 and y%5<3)
                row.append(tuple(max(0,min(255,c+n)) for c in base)+(255 if stem or petal else 0,))
        rows.append(row)
    if not plant:png(root/'src/main/resources/assets/beyond_unknown/textures/block'/(name+'.png'),rows)
    else:
        def ck(k,d):return struct.pack('>I',len(d))+k+d+struct.pack('>I',zlib.crc32(k+d)&0xffffffff)
        raw=b''.join(b'\x00'+bytes(c for pix in row for c in pix) for row in rows)
        p=root/'src/main/resources/assets/beyond_unknown/textures/block'/(name+'.png')
        p.write_bytes(b'\x89PNG\r\n\x1a\n'+ck(b'IHDR',struct.pack('>IIBBBBB',16,16,8,6,0,0,0))+ck(b'IDAT',zlib.compress(raw))+ck(b'IEND',b''))
